query DioneItems($first: Int, $after: String) {
  dioneItems(first: $first, after: $after) {
    nodes {
      id
      reportId
      source
      sourceId
      title
      kind
      date
      detail
      url
      section
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

